import{_ as o,r as t,o as i,c as r,e as a,a as c,s as p}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Tailor Localization - October CMS - 4.x","titleTemplate":false,"description":"Learn how to translate Tailor content across multiple sites.","frontmatter":{"subtitle":"Learn how to translate Tailor content across multiple sites."},"headers":[{"level":2,"title":"Enabling Multisite","slug":"enabling-multisite","link":"#enabling-multisite","children":[]},{"level":2,"title":"Synchronization Modes","slug":"synchronization-modes","link":"#synchronization-modes","children":[]},{"level":2,"title":"Propagating Content","slug":"propagating-content","link":"#propagating-content","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/multisite/tailor.md","filePath":"4.x/cms/multisite/tailor.md"}'),d={name:"4.x/cms/multisite/tailor.md"};function u(h,e,g,m,y,k){const s=t("pre-heading"),n=t("post-heading"),l=t("VideoBlockLink");return i(),r("div",null,[a(s),e[0]||(e[0]=c("h1",null,"Tailor Localization",-1)),a(n),a(l,{src:"https://www.youtube.com/watch?v=_kX7P3SEHg8",title:"Multisite Demo",description:"This video demonstrates how to create multilingual sites with October CMS Multisite.",prompt:"Watch the demonstration"}),e[1]||(e[1]=p(`<div class="custom-block aside"><p>View the <a href="./multisite.html">Multisite article</a> to learn how to configure sites and languages.</p></div><p>Tailor blueprints support multisite and localization, allowing content to be unique or synchronized across configured sites. This article covers enabling multisite on blueprints, controlling which fields are translatable, and synchronizing records across sites.</p><h2 id="enabling-multisite"><a href="#enabling-multisite" class="header-anchor">#</a> Enabling Multisite</h2><p>Blueprints do not use <a href="./multisite.html">multisite capabilities</a> by default. You may use the <code>multisite</code> property to enable this. When enabled, records can be unique to each configured site.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token comment"># ...</span>
<span class="token key atrule">multisite</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>When multisite is enabled, all fields in the blueprint become translatable. To keep the same value for a field, set the <code>translatable</code> property to false. In this example, when saving the record the <strong>name</strong> field will be copied to every site when it is saved.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ...</span>
<span class="token key atrule">multisite</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Full Name
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
        <span class="token key atrule">translatable</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><h2 id="synchronization-modes"><a href="#synchronization-modes" class="header-anchor">#</a> Synchronization Modes</h2><p>You may set the multisite value to <strong>sync</strong> to keep the records synchronized across sites, which is helpful for categories and tags. When using sync, each record will always exist on every site, although the content can be different.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> sync
</code></pre></div><p>When using <a href="./multisite.html">Site Groups</a>, the records will be propagated to all sites within that group. This can be changed by setting the <code>multisite</code> property to <strong>all</strong> to sync within all sites.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> all
</code></pre></div><p>Setting to <strong>locale</strong> will sync the records to all sites that share the same locale.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> locale
</code></pre></div><p>The following values are supported by the <code>multisite</code> property.</p><div class="table"><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>true</code></td><td>Records are unique per site, all fields are translatable</td></tr><tr><td><code>false</code></td><td>Multisite is disabled (default)</td></tr><tr><td><code>sync</code></td><td>Records are synchronized within the site group</td></tr><tr><td><code>all</code></td><td>Records are synchronized across all sites</td></tr><tr><td><code>locale</code></td><td>Records are synchronized to sites sharing the same locale</td></tr></tbody></table></div><h2 id="propagating-content"><a href="#propagating-content" class="header-anchor">#</a> Propagating Content</h2><p>When using the <strong>sync</strong> option for multisite, you may retroactively propagate records using the <code>tailor:propagate</code> command.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:propagate
</code></pre></div><p>To propagate a single blueprint use the <code>--blueprint</code> option and specify its handle.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:propagate <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Category&quot;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./multisite.html">Multisite</a></li><li><a href="./localization.html">Theme Localization</a></li><li><a href="./../tailor/blueprints.html">Tailor Blueprints</a></li><li><a href="./../../extend/multisite/multisite.html">Multisite Trait</a></li><li><a href="./../../extend/multisite/translatable.html">Translatable Trait</a></li></ul></div>`,23))])}const v=o(d,[["render",u]]);export{f as __pageData,v as default};
